const stageMap = {
  screening: 'Screening',
  interview: 'Interview',
  interviewing: 'Interview',
  offer: 'Offer',
  offered: 'Offer'
};

return $input.all().map((item) => {
  const rawStage = String(item.json.stage ?? item.json.Stage ?? item.json.current_stage ?? '').trim();
  const normalized = stageMap[rawStage.toLowerCase()] ?? rawStage;
  return {
    json: {
      ...item.json,
      stage: normalized
    },
    pairedItem: item.pairedItem
  };
});

const rows = $input.all().map((item) => item.json);
const stageMap = {
  screening: 'Screening',
  interview: 'Interview',
  interviewing: 'Interview',
  offer: 'Offer',
  offered: 'Offer'
};
const firstValue = (row, names) => {
  for (const name of names) {
    if (row[name] !== undefined && row[name] !== null && row[name] !== '') return row[name];
  }
  return undefined;
};
const numberValue = (value) => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
};
const groups = new Map();

for (const row of rows) {
  const rawStage = String(firstValue(row, ['stage', 'Stage', 'current_stage', 'Current Stage']) ?? 'Unknown').trim();
  const stage = stageMap[rawStage.toLowerCase()] ?? rawStage;
  if (!groups.has(stage)) groups.set(stage, { stage, timeToHire: [], daysInStage: [], count: 0 });
  const group = groups.get(stage);
  group.count += 1;

  const timeToHire = numberValue(firstValue(row, [
    'time_to_hire_days', 'Time to Hire', 'Time-to-Hire', 'days_to_hire', 'Days to Hire'
  ]));
  const daysInStage = numberValue(firstValue(row, [
    'days_in_stage', 'Days in Stage', 'days_active', 'historical_days_in_stage'
  ]));
  if (timeToHire !== null) group.timeToHire.push(timeToHire);
  if (daysInStage !== null) group.daysInStage.push(daysInStage);
}

const average = (values) => values.length
  ? Math.round((values.reduce((sum, value) => sum + value, 0) / values.length) * 10) / 10
  : null;

return Array.from(groups.values()).map((group) => ({
  json: {
    stage: group.stage,
    historical_avg_time_to_hire_days: average(group.timeToHire),
    historical_avg_days_in_stage: average(group.daysInStage),
    historical_sample_size: group.count
  }
}));

