const records = $input.first().json.candidate_records ?? [];
const stages = ['Screening', 'Interview', 'Offer'];
const firstValue = (row, names) => {
  for (const name of names) {
    if (row[name] !== undefined && row[name] !== null && row[name] !== '') return row[name];
  }
  return undefined;
};
const numberValue = (value) => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
};
const round = (value) => Math.round(value * 10) / 10;
const stageMetrics = Object.fromEntries(stages.map((stage) => [stage, {
  stage,
  candidates: 0,
  stalled: 0,
  days: [],
  historicalDays: [],
  historicalTimeToHire: []
}]));
const quality = {
  missing_stage: 0,
  missing_days_active: 0,
  missing_feedback: 0,
  missing_historical_benchmark: 0
};
let stalled = 0;
let healthy = 0;
let totalDays = 0;
let daysCount = 0;

for (const row of records) {
  const stage = String(firstValue(row, ['stage', 'Stage']) ?? '').trim();
  const days = numberValue(firstValue(row, ['days_active', 'Days in Stage', 'days_in_stage']));
  const health = String(firstValue(row, ['candidate_health']) ?? '');
  const feedback = firstValue(row, ['feedback_notes', 'Feedback Notes', 'feedback']);
  const historicalDays = numberValue(firstValue(row, ['historical_avg_days_in_stage']));
  const historicalTTH = numberValue(firstValue(row, ['historical_avg_time_to_hire_days']));

  if (!stage) quality.missing_stage += 1;
  if (days === null) quality.missing_days_active += 1;
  if (feedback === undefined) quality.missing_feedback += 1;
  if (historicalDays === null && historicalTTH === null) quality.missing_historical_benchmark += 1;

  if (health === 'Stalled') stalled += 1;
  if (health === 'Healthy') healthy += 1;
  if (days !== null) {
    totalDays += days;
    daysCount += 1;
  }

  if (stageMetrics[stage]) {
    const metric = stageMetrics[stage];
    metric.candidates += 1;
    if (health === 'Stalled') metric.stalled += 1;
    if (days !== null) metric.days.push(days);
    if (historicalDays !== null) metric.historicalDays.push(historicalDays);
    if (historicalTTH !== null) metric.historicalTimeToHire.push(historicalTTH);
  }
}

const summarizedStages = Object.values(stageMetrics).map((metric) => ({
  stage: metric.stage,
  candidates: metric.candidates,
  stalled_candidates: metric.stalled,
  stalled_rate_pct: metric.candidates ? round((metric.stalled / metric.candidates) * 100) : 0,
  average_days_active: metric.days.length ? round(metric.days.reduce((a, b) => a + b, 0) / metric.days.length) : null,
  historical_avg_days_in_stage: metric.historicalDays.length ? round(metric.historicalDays.reduce((a, b) => a + b, 0) / metric.historicalDays.length) : null,
  historical_avg_time_to_hire_days: metric.historicalTimeToHire.length ? round(metric.historicalTimeToHire.reduce((a, b) => a + b, 0) / metric.historicalTimeToHire.length) : null
}));

return [{
  json: {
    aggregated_metrics: {
      generated_at: new Date().toISOString(),
      total_candidates: records.length,
      health_counts: { Healthy: healthy, Stalled: stalled },
      stalled_rate_pct: records.length ? round((stalled / records.length) * 100) : 0,
      average_days_active: daysCount ? round(totalDays / daysCount) : null,
      stage_metrics: summarizedStages,
      data_quality: quality
    }
  }
}];
